const ALTERNATE_ULTIMATES=[
{name:'剣閃領域',desc:'6秒間、通常攻撃の最初の直撃に150%の追撃を加える（最大5回・射程180）。倒した相手・スキル・継続ダメージは対象外。自動連斬ではなく、自分の通常攻撃で放つ。'},
{name:'城壁崩し',desc:'発動地点で0.9秒構え、前方420へ800%の一撃。通常敵を最大120押し出す。ボスは動かない。移動しても起点と方向は固定。防御軽減は付かない。'},
{name:'星核の牢',desc:'照準地点に半径200の星核を3秒設置。0.5秒ごとに70%の攻撃と通常敵を最大30吸引し、最後に500%で爆発。ボスは吸引しない。壁で遮られる。'},
{name:'一矢天命',desc:'1.4秒後、発動地点から固定した方向へ長さ900・半幅24の一射。射線上の最初の敵へ1200%、2体目へ400%。3体目以降と壁の向こうには当たらない。'},
{name:'夜渡りの帰刃',desc:'発動地点に影を残し、2秒後に現在位置と影の周囲140へ各450%。影から500以内・射線と着地の安全が確保されていれば影へ帰還。無敵は付かず、移動不可でも現在位置の斬撃は放つ。2地点が同じなら斬撃は1回。'},
{name:'命魂の庇護',desc:'8秒間、最大HPの60%を肩代わりする盾を得る。期間中HPが30%以下になった時、一度だけ最大HP25%を回復。致命傷を防ぐ効果ではなく、攻撃もしない。'},
{name:'幻獣の奔流',desc:'発動地点から前方600へ3列の幻獣を走らせる。各列は半幅35、各敵に一度ずつ200%。敵を動かして複数列に誘導できる。同行中の仲間は呼び直さず、強化もしない。'},
{name:'竜王の裁き',desc:'契約竜の幻影を照準地点へ降ろし、1.5秒後に半径230へ1000%の一撃と契約竜の属性を付着。契約が必要。同行竜や騎乗状態は維持し、ブレス連射にはならない。'}
];
function makeAlternateUltimate(base){if(combatTechnique().ultimate!==1)return base;const id=combatProfessionType(),s={...base,alternate:true,type:8+id,job:id,owner:p,world:dungeon,origin:{x:p.x,y:p.y},charges:5,seen:[new Set(),new Set(),new Set()],next:.5};if(!lineClear(p,s)){let distance=dist(p,s);for(let d=distance;d>=0;d-=10){s.x=p.x+Math.cos(s.angle)*d;s.y=p.y+Math.sin(s.angle)*d;if(lineClear(p,s))break;}}if(id===5){classBarrier=Math.max(classBarrier,maxhp()*.6);classBarrierTime=Math.max(classBarrierTime,8);}return s;}
function alternateUltimateValid(s){return s.owner===p&&s.world===dungeon&&!dead&&p?.hp>0&&dist(p,s.origin)<=1000;}
function alternateUltimateHit(s,targets,mult){const kind=classHitKind;classHitKind='ultimate';try{for(const e of targets)if(e.hp>0&&enemies.includes(e)){hit(e,s.power*mult);if(s.job===7)applyElements(e,[TAME_DRAGONS.find(d=>d[0]===s.dragon)?.[2]??0],s.power*mult);}}finally{classHitKind=kind;}}
function alternateUltimateArea(s,center,radius,mult){if(!lineClear(p,center))return;const targets=enemies.filter(e=>e.hp>0&&dist(e,center)<=radius&&lineClear(center,e));alternateUltimateHit(s,targets,mult);burst(center.x,center.y,radius,PROFESSIONS[s.job].color);return targets;}
const alternateProfessionBase=profession;profession=()=>{const base=alternateProfessionBase();return combatTechnique().ultimate===1?{...base,ultimate:ALTERNATE_ULTIMATES[combatProfessionType()].name,desc:ALTERNATE_ULTIMATES[combatProfessionType()].desc+(advancedJob()?' 上位職：攻撃威力20%増。':'')}:base;};
const alternateAdvanceBase=advanceUltimate;advanceUltimate=dt=>{const s=ultimateState;if(!s?.alternate)return alternateAdvanceBase(dt);if(!alternateUltimateValid(s)){ultimateState=null;return;}if(paused||!Number.isFinite(dt)||dt<=0)return;s.time+=dt;
 if(s.job===0){if(s.time>=6||s.charges<=0)ultimateState=null;return;}
 if(s.job===1&&s.time>=.9){const targets=enemies.filter(e=>e.hp>0&&dist(e,s.origin)<=420&&lineClear(s.origin,e)&&Math.cos(Math.atan2(e.y-s.origin.y,e.x-s.origin.x)-s.angle)>.3);alternateUltimateHit(s,targets,8);for(const e of targets)if(e.hp>0&&!e.boss&&!e.dummy)moveActor(e,Math.cos(s.angle)*120,Math.sin(s.angle)*120);burst(s.origin.x,s.origin.y,420,PROFESSIONS[1].color);ultimateState=null;}
 else if(s.job===2){while(s.next<=3&&s.time+1e-8>=s.next){s.next+=.5;const targets=alternateUltimateArea(s,s,200,.7)||[];for(const e of targets)if(e.hp>0&&!e.boss&&!e.dummy){const d=dist(e,s)||1;moveActor(e,(s.x-e.x)/d*Math.min(30,d),(s.y-e.y)/d*Math.min(30,d));}}if(s.time+1e-8>=3){alternateUltimateArea(s,s,200,5);ultimateState=null;}}
 else if(s.job===3&&s.time+1e-8>=1.4){const ray=enemies.filter(e=>e.hp>0&&lineClear(s.origin,e)).map(e=>{const dx=e.x-s.origin.x,dy=e.y-s.origin.y;return{e,along:dx*Math.cos(s.angle)+dy*Math.sin(s.angle),side:Math.abs(-dx*Math.sin(s.angle)+dy*Math.cos(s.angle))};}).filter(v=>v.along>=0&&v.along<=900&&v.side<=24).sort((a,b)=>a.along-b.along).slice(0,2);ray.forEach((v,i)=>alternateUltimateHit(s,[v.e],i?4:12));paintLinkLine(s.origin,{x:s.origin.x+Math.cos(s.angle)*900,y:s.origin.y+Math.sin(s.angle)*900},PROFESSIONS[3].color,7);playSound('arrow',p.x,p.y);ultimateState=null;}
 else if(s.job===4&&s.time+1e-8>=2){const here={x:p.x,y:p.y};alternateUltimateArea(s,here,140,4.5);if(dist(p,s.origin)<=500&&lineClear(p,s.origin)){if(dist(here,s.origin)>1)alternateUltimateArea(s,s.origin,140,4.5);if(passable(s.origin.x,s.origin.y,13)&&enemies.every(e=>e.hp<=0||dist(e,s.origin)>enemyHitRadius(e)+13)){p.x=s.origin.x;p.y=s.origin.y;route=[];moveGoal=null;attackTarget=null;playerAction=null;}}ultimateState=null;}
 else if(s.job===5){if(s.time<8&&!s.rescued&&p.hp<=maxhp()*.3){s.rescued=true;p.hp=Math.min(maxhp(),p.hp+maxhp()*.25);burst(p.x,p.y,80,PROFESSIONS[5].color);playSound('heal',p.x,p.y);}if(s.time>=8)ultimateState=null;}
 else if(s.job===6){const end=Math.min(600,s.time*400),start=Math.max(0,(s.time-dt)*400);for(let i=0;i<3;i++){const offset=(i-1)*90;const targets=enemies.filter(e=>{const dx=e.x-s.origin.x,dy=e.y-s.origin.y,along=dx*Math.cos(s.angle)+dy*Math.sin(s.angle),side=-dx*Math.sin(s.angle)+dy*Math.cos(s.angle);return e.hp>0&&!s.seen[i].has(e)&&along>=start-25&&along<=end+25&&Math.abs(side-offset)<=35&&lineClear(s.origin,e);});targets.forEach(e=>s.seen[i].add(e));alternateUltimateHit(s,targets,2);}if(s.time>=1.5)ultimateState=null;}
 else if(s.job===7&&s.time+1e-8>=1.5){alternateUltimateArea(s,s,230,10);playSound('fire',s.x,s.y);ultimateState=null;}
};
const alternateNormalHitBase=hit;hit=(e,d)=>{const s=ultimateState,before=e?.hp,training=e?.trainingHits||0,eligible=s?.alternate&&s.job===0&&s.charges>0&&s.time<6&&alternateUltimateValid(s)&&!paused&&cadenceNormalAction&&classHitKind==='normal'&&!classNormalHit&&!treeExplosion&&!e?.dotTick&&e?.hp>0&&dist(p,e)<=180&&lineClear(p,e);const result=alternateNormalHitBase(e,d);if(eligible&&ultimateState===s&&e.hp>0&&(e.hp<before||(e.trainingHits||0)>training)){s.charges--;alternateUltimateHit(s,[e],1.5);burst(e.x,e.y,45,PROFESSIONS[0].color);}return result;};
const alternateDrawBase=drawGroundEffects;drawGroundEffects=()=>{const s=ultimateState;if(!s?.alternate)return alternateDrawBase();ultimateState=null;try{alternateDrawBase();}finally{ultimateState=s;}if(!alternateUltimateValid(s))return;const color=PROFESSIONS[s.job].color;if([1,3,6].includes(s.job)){const length=s.job===1?420:s.job===3?900:Math.min(600,s.time*400);for(let i=0;i<(s.job===6?3:1);i++){const offset=s.job===6?(i-1)*90:0,end={x:s.origin.x+Math.cos(s.angle)*length-Math.sin(s.angle)*offset,y:s.origin.y+Math.sin(s.angle)*length+Math.cos(s.angle)*offset};paintLinkLine(s.origin,end,color,s.job===3?3:5);groundRing(end.x,end.y,s.job===6?35:24,color,2);if(s.job===6&&visibleAt(end.x,end.y))actorSprite(wolfSheet,end.x,end.y,85,'walk',s.time,Math.cos(s.angle)>0?1:-1,.6);}}else{const center=[2,7].includes(s.job)?s:s.job===4?s.origin:p;groundRing(center.x,center.y,s.job===2?200:s.job===7?230:s.job===4?140:55,color,3);if(s.job===7&&visibleAt(s.x,s.y))actorSprite(dragonSheet,s.x,s.y,210,'attack',s.time,1,.65);}};
const alternateGuideBase=jobGuideContent;jobGuideContent=(topic,selected)=>topic==='ultimate'?combatUltimateOptions(selected).map(t=>'<h3>'+gearEscape(t.name)+'</h3><p>'+gearEscape(t.desc)+'</p>').join('')+'<p>どちらもゲージ100。スキル画面で切り替え。'+(selected>=8?'上位職は攻撃威力20%増。':'')+'</p>':alternateGuideBase(topic,selected);
